const transpose=a=>a[0].map((_,i)=>a.map(r=>r[i]));
const matmul=(a,b)=>a.map(r=>transpose(b).map(c=>dot(r,c)));
const matvec=(a,v)=>a.map(r=>dot(r,v));
const determinant=m=>m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);
const trace=m=>m[0][0]+m[1][1]+m[2][2];
