const closeMatrix=(a,b,eps=1e-5)=>a.every((r,i)=>r.every((x,j)=>Math.abs(x-b[i][j])<=eps));

export function parseXYZ(text){
  const lines=text.replace(/\r/g,"").split("\n");
  if(lines.length<2)throw new Error("XYZ input needs an atom count and comment line.");
  if(!/^\s*\d+\s*$/.test(lines[0]))throw new Error("The first line must be a positive integer atom count.");
  const count=Number(lines[0]);if(count<1)throw new Error("Atom count must be positive.");
  const records=lines.slice(2);while(records.length&&!records.at(-1).trim())records.pop();
  if(records.length!==count)throw new Error(`Expected ${count} atom records, found ${records.length}.`);
  const symbols=[],coordinates=[];
  records.forEach((line,index)=>{const fields=line.trim().split(/\s+/);if(fields.length!==4)throw new Error(`Line ${index+3}: expected an element and 3 coordinates.`);if(!ELEMENTS.has(fields[0]))throw new Error(`Line ${index+3}: invalid element “${fields[0]}”.`);const xyz=fields.slice(1).map(Number);if(xyz.some(x=>!Number.isFinite(x)))throw new Error(`Line ${index+3}: coordinates must be finite numbers.`);symbols.push(fields[0]);coordinates.push(xyz)});
  return {symbols,coordinates,comment:lines[1].trim()||"Untitled molecule"};
}
