export function analyzeMolecule(symbols,coordinates,tolerance=0.1){if(!Number.isFinite(tolerance)||tolerance<=0)throw new Error("Tolerance must be a positive finite number.");if(symbols.length!==coordinates.length||!symbols.length)throw new Error("Symbols and coordinates must contain the same positive atom count.");const center=[0,1,2].map(k=>coordinates.reduce((s,v)=>s+v[k],0)/coordinates.length),centered=coordinates.map(v=>sub(v,center));if(symbols.length===1)return {group:"Kh",description:groupDescription("Kh"),centered,operations:[operationInfo(I,0)]};let far=[0,1],distance=-1;for(let i=0;i<centered.length;i++)for(let j=i+1;j<centered.length;j++){const d=norm(sub(centered[i],centered[j]));if(d>distance){distance=d;far=[i,j]}}const axis=unit(sub(centered[far[1]],centered[far[0]])),linear=centered.every(v=>norm(sub(v,scale(axis,dot(v,axis))))<=tolerance);if(linear){const inverted=matchingPermutation(symbols,centered,scaleMatrix(I,-1),tolerance)!==null,group=inverted?"Dinfh":"Cinfv";const matrices=inverted?[I,scaleMatrix(I,-1)]:[I];return {group,description:groupDescription(group),centered,operations:matrices.map(operationInfo),linear:true,axis}}
  const matrices=discoverOperations(symbols,centered,tolerance),group=classifyOperations(matrices);return {group,description:groupDescription(group),centered,operations:matrices.map(operationInfo)}
}

