export function analyzeMolecule(symbols,coordinates,tolerance=0.1){if(!Number.isFinite(tolerance)||tolerance<=0)throw new Error("Tolerance must be a positive finite number.");if(symbols.length!==coordinates.length||!symbols.length)throw new Error("Symbols and coordinates must contain the same positive atom count.");const center=[0,1,2].map(k=>coordinates.reduce((s,v)=>s+v[k],0)/coordinates.length),centered=coordinates.map(v=>sub(v,center));if(symbols.length===1)return {group:"Kh",description:groupDescription("Kh"),centered,operationCount:"∞",operations:[operationInfo(I,0),{symbol:"C∞",name:"Arbitrary rotation",detail:"About any axis",axis:[0,0,1]},{symbol:"σ",name:"Arbitrary reflection",detail:"Through any plane",axis:[0,1,0],plane:true},{symbol:"i",name:"Inversion",detail:"Through the atom",point:true}]};let far=[0,1],distance=-1;for(let i=0;i<centered.length;i++)for(let j=i+1;j<centered.length;j++){const d=norm(sub(centered[i],centered[j]));if(d>distance){distance=d;far=[i,j]}}const axis=unit(sub(centered[far[1]],centered[far[0]])),linear=centered.every(v=>norm(sub(v,scale(axis,dot(v,axis))))<=tolerance);if(linear){const inverted=matchingPermutation(symbols,centered,scaleMatrix(I,-1),tolerance)!==null,group=inverted?"Dinfh":"Cinfv",operations=[operationInfo(I,0),{symbol:"C∞",name:"Continuous rotation",detail:"About the molecular axis",axis},{symbol:"σv",name:"Vertical mirrors",detail:"Infinitely many planes",axis:unit(cross(axis,Math.abs(axis[0])<.8?[1,0,0]:[0,1,0])),plane:true}];if(inverted)operations.push({symbol:"i",name:"Inversion",detail:"Through the molecular center",point:true},{symbol:"σh",name:"Horizontal mirror",detail:"Normal to the molecular axis",axis,plane:true},{symbol:"C2",name:"Perpendicular rotations",detail:"Infinitely many twofold axes",axis:unit(cross(axis,Math.abs(axis[0])<.8?[1,0,0]:[0,1,0]))});return {group,description:groupDescription(group),centered,operationCount:"∞",operations,linear:true,axis}}
  const matrices=discoverOperations(symbols,centered,tolerance),group=classifyOperations(matrices);return {group,description:groupDescription(group),centered,operationCount:matrices.length,operations:matrices.map(operationInfo)}
}

