const {analyzeMolecule, parseXYZ, internals} = require('./docs/pgmol-core.mjs');
const fs = require('fs');

// The D6h S3/S6 labels and detail strings look swapped.
// An S3 operation = C3 * sigma_h = rotation by 120° then reflect.
// An S6 operation = C6 * sigma_h = rotation by 60° then reflect.
//
// The code for improper rotations in operationInfo (line 37):
//   const proper=scaleMatrix(matrix,-1), order=rotationOrder(proper),
//         angle=acos(...)  
//   symbol: S\${order}
//   detail: Rotate \${angle}°, then reflect
//
// For S3 (matrix = sigma_h * C3):
//   proper = -S3 = -(sigma_h * C3) = -sigma_h * C3
//   -sigma_h = diag(1,1,-1) * (-1) = diag(-1,-1,1)? No.
//   Actually: S3 = sigma_h * C3. The matrix for sigma_h about z: [[1,0,0],[0,1,0],[0,0,-1]]
//   C3 about z: [[cos120,-sin120,0],[sin120,cos120,0],[0,0,1]]
//   S3 = sigma_h * C3: same as C3 but z-component negated:
//     [[cos120,-sin120,0],[sin120,cos120,0],[0,0,-1]]
//   proper = -S3 = [[-cos120,sin120,0],[-sin120,-cos120,0],[0,0,1]]
//   This is a rotation by 180°-120° = 60° about z. (cos(180-120)=cos60=0.5, -cos120=0.5 ✓)
//   So proper component has angle 60°, order = rotationOrder = ... 
//   trace(proper) = -cos120 + (-cos120) + 1 = 2*0.5+1 = 2.0
//   angle = acos((2-1)/2) = acos(0.5) = 60°. rotationOrder: 60° → n=6 (C6^1 has order 6).
//   Wait: proper is a rotation by 60°. power(proper,6) = rotation by 360° = I. So order=6.
//   
//   So S3 is labeled S6 with 'Rotate 60°, then reflect'. That's WRONG.
//   The S3 operation rotates by 120°, not 60°.

// The issue: for an improper rotation S_n, the 'proper component' via -S_n is NOT C_n.
// -S_n = -(sigma_h * C_n) = (-sigma_h) * C_n = inversion_component * C_n
// This is NOT the same as C_n. It's -sigma_h * C_n.
// -sigma_h is a rotation by 180° about the normal axis (C2 about the S_n axis).
// So -S_n = C2 * C_n. If S_n axis is z: -S3 = C2(z) * C3(z) = rotation by 120+180=300° = -60°.
// That's equivalent to C6^5, which has order 6.

// So the proper component approach (-matrix) doesn't extract C_n but instead gives
// C2*C_n, which has a different rotation angle and order.

// The CORRECT approach: for an improper rotation about axis n̂ with angle θ,
// the Schoenflies label is S_n where θ = 2π/n, i.e., n = 2π/θ.
// The angle θ can be extracted from the improper rotation matrix trace:
// trace(S_n) = 2cos(θ) - 1  (for rotation by θ about an axis, then reflect perp to that axis)
// So cos(θ) = (trace+1)/2, θ = acos((trace+1)/2)
// Then n = round(2π/θ).

